"""V2 SDK client for the auto-generated file domain."""

from __future__ import annotations

from typing import Final

from ai.backend.client.v2.base_domain import BaseDomainClient
from ai.backend.common.data.entity.auto_generated_file import AutoGeneratedFileID
from ai.backend.common.dto.manager.v2.auto_generated_file.request import (
    AddAutoGeneratedFileRevisionInput,
    AutoGeneratedFileScopeInput,
    CreateAutoGeneratedFileInput,
    MySearchAutoGeneratedFilesInput,
    ScopedSearchAutoGeneratedFilesInput,
    SearchAutoGeneratedFileRevisionsInput,
)
from ai.backend.common.dto.manager.v2.auto_generated_file.response import (
    AddAutoGeneratedFileRevisionPayload,
    CreateAutoGeneratedFilePayload,
    GetAutoGeneratedFilePayload,
    PurgeAutoGeneratedFilePayload,
    SearchAutoGeneratedFileRevisionsPayload,
    SearchAutoGeneratedFilesPayload,
    SwitchDefaultAutoGeneratedFilePayload,
)

_PATH: Final = "/v2/auto-generated-files"


class V2AutoGeneratedFileClient(BaseDomainClient):
    """SDK client for auto-generated file operations."""

    async def create(self, request: CreateAutoGeneratedFileInput) -> CreateAutoGeneratedFilePayload:
        """Add a file that is not the default of its path."""
        return await self._client.typed_request(
            "POST", _PATH, request=request, response_model=CreateAutoGeneratedFilePayload
        )

    async def get(self, auto_generated_file_id: AutoGeneratedFileID) -> GetAutoGeneratedFilePayload:
        """Read one file."""
        return await self._client.typed_request(
            "GET",
            f"{_PATH}/{auto_generated_file_id}",
            response_model=GetAutoGeneratedFilePayload,
        )

    async def add_revision(
        self, request: AddAutoGeneratedFileRevisionInput
    ) -> AddAutoGeneratedFileRevisionPayload:
        """Add the next revision of a file's content and permission."""
        return await self._client.typed_request(
            "POST",
            f"{_PATH}/{request.auto_generated_file_id}/revisions",
            request=request,
            response_model=AddAutoGeneratedFileRevisionPayload,
        )

    async def search_revisions(
        self, request: SearchAutoGeneratedFileRevisionsInput
    ) -> SearchAutoGeneratedFileRevisionsPayload:
        """Search the revisions of a file."""
        return await self._client.typed_request(
            "POST",
            f"{_PATH}/{request.auto_generated_file_id}/revisions/search",
            request=request,
            response_model=SearchAutoGeneratedFileRevisionsPayload,
        )

    async def scoped_search(
        self, request: ScopedSearchAutoGeneratedFilesInput
    ) -> SearchAutoGeneratedFilesPayload:
        """Search the files of the named domains, projects and users."""
        return await self._client.typed_request(
            "POST",
            f"{_PATH}/scoped/search",
            request=request,
            response_model=SearchAutoGeneratedFilesPayload,
        )

    async def my_search(
        self, request: MySearchAutoGeneratedFilesInput
    ) -> SearchAutoGeneratedFilesPayload:
        """Search the caller's own files."""
        return await self._client.typed_request(
            "POST",
            f"{_PATH}/my/search",
            request=request,
            response_model=SearchAutoGeneratedFilesPayload,
        )

    async def switch_default(
        self, auto_generated_file_id: AutoGeneratedFileID, scope: AutoGeneratedFileScopeInput
    ) -> SwitchDefaultAutoGeneratedFilePayload:
        """Make a file the default of its path in its scope."""
        return await self._client.typed_request(
            "POST",
            f"{_PATH}/{auto_generated_file_id}/switch-default",
            request=scope,
            response_model=SwitchDefaultAutoGeneratedFilePayload,
        )

    async def purge(
        self, auto_generated_file_id: AutoGeneratedFileID
    ) -> PurgeAutoGeneratedFilePayload:
        """Remove a file that is not the default of its path."""
        return await self._client.typed_request(
            "DELETE",
            f"{_PATH}/{auto_generated_file_id}",
            response_model=PurgeAutoGeneratedFilePayload,
        )
